    const auto directory=folder/(unrecorded?"coding-async-unrecorded":"coding-async");check(std::filesystem::create_directory(directory),"Async worker requires a fresh workspace");write(directory/"AGENTS.md","CODING_ASYNC_GUIDANCE\n");
