    const std::string id=unrecorded?"rpc-coding-async-unrecorded":"rpc-coding-async",session=id+"-session";store.create_session(session,"Production asynchronous worker join").get();ExecutionPlatform service(store,settings,1,2,[&](PersistenceService& actual,const AgentSettings& captured){return make_agent_worker_coding_executor(actual,captured,image);});service.select_session_agent(session,service.agent_definitions().front(),0);std::unique_ptr<XlangSqlite> fault;if(unrecorded){fault=std::make_unique<XlangSqlite>((folder/"state.sqlite").string(),imports);fault->execute("CREATE TRIGGER fixture_async_join_abort BEFORE INSERT ON events WHEN NEW.kind='agent.background_processes_joined' BEGIN SELECT RAISE(ABORT,'fixture_async_join_abort'); END");}service.submit(id,session,"Run the asynchronous command and inspect its actual terminal result.");
